  /** @type {SettingControlConfig[]} */
  let configs = [];
  // Argon: expose only the curated engines from onboarding. The upstream
  // list contains trackers and site-specific engines (eBay, Reddit, Amazon,
  // YouTube, Perplexity, regional portals) that Argon does not offer.
  for (let engine of await lazy.SearchService.getEngines()) {
    if (!window.isArgonSearchEngine?.(engine)) {
      continue;
